insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_98_v1'
from (values
('127.752.d.4',3,'A fire service recruit reviews radio traffic, written reports, hand signals and face-to-face briefings. These show the:','["different types of communication used in the fire service", "parts of a hose", "classes of fire", "kinds of ladders"]'::jsonb,0,'Fire crews use verbal, written, radio and nonverbal communication.','original'),
('127.752.d.4',4,'A firefighter uses a hand signal to tell a pump operator to stop water when a roaring engine drowns out voices. This is:','["a report", "nonverbal communication", "written communication", "a letter"]'::jsonb,1,'Signals work when noise blocks speech.','original'),
('127.752.d.1.A',3,'A recruit sets the goal ''Pass the physical agility test in 12 weeks by training four days a week.'' This is built using the steps for a:','["random wish", "daydream", "SMART goal", "vague plan"]'::jsonb,2,'SMART goals are specific, measurable, achievable, relevant and time-bound.','original'),
('127.752.d.1.A',4,'In a SMART goal, the ''M'' stands for:','["mandatory", "moderate", "magical", "measurable"]'::jsonb,3,'A measurable goal can be tracked.','original'),
('127.752.d.1.B',3,'A student explains that tracking daily sit-ups, finishing a 5K and improving personal bests each show different benefits of setting goals. These are:','["process, outcome and performance benefits of SMART goals", "only penalties", "only prizes", "no benefits"]'::jsonb,0,'SMART goals help focus effort and track progress.','original'),
('127.752.d.1.B',4,'Writing a goal with a deadline mainly helps a recruit to:','["avoid planning", "stay focused and measure progress", "remove choices", "delay effort"]'::jsonb,1,'Deadlines give structure.','original'),
('127.752.d.1.C',3,'After setting a goal to earn a fire certification, a recruit lists tasks, resources, due dates and possible obstacles. This is creating an:','["grocery list", "excuse list", "action plan", "wish list"]'::jsonb,2,'Action plans break goals into steps.','original'),
('127.752.d.1.C',4,'A good action plan for a SMART goal includes:','["only a slogan", "only a dream", "no dates", "clear tasks, deadlines and resources"]'::jsonb,3,'Actions need tasks and timelines.','original'),
('127.752.d.2.A',3,'A student compares job duties and hiring needs for private-sector fire protection jobs such as industrial brigades. This identifies:','["employment requirements and roles in private fire protection", "farm jobs", "school jobs", "public sector only"]'::jsonb,0,'Private employers hire fire protection staff.','original'),
('127.752.d.2.A',4,'A refinery''s fire brigade is an example of:','["a state park", "private-sector fire protection", "a federal agency", "a volunteer city department"]'::jsonb,1,'Industry runs its own brigades.','original'),
('127.752.d.2.B',3,'A recruit studies how municipal fire departments hire firefighters and what they do on shift. This identifies roles in:','["only airports", "only forests", "city-run career fire services", "only ships"]'::jsonb,2,'Municipal departments serve cities.','original'),
('127.752.d.2.B',4,'A career municipal firefighter is typically employed by a:','["movie studio", "private yacht club", "bank", "city or town"]'::jsonb,3,'Municipal means city-run.','original'),
('127.752.d.2.C',3,'A student explores jobs in a county fire marshal''s office and a rural volunteer department. This identifies:','["roles in county, rural and volunteer fire services", "mining roles", "school roles", "retail roles"]'::jsonb,0,'Many fire jobs are county and volunteer.','original'),
('127.752.d.2.C',4,'Volunteer firefighters serve primarily by:','["only teaching", "responding to calls with training but often without regular pay", "only cooking", "working full time salaried"]'::jsonb,1,'Volunteers serve their community.','original'),
('127.752.d.2.D',3,'A recruit researches Texas A&M Forest Service wildland roles and airport firefighting careers. This identifies:','["restaurant jobs", "office jobs only", "roles in wildland and airport fire protection", "bank jobs"]'::jsonb,2,'Specialty fire jobs exist.','original'),
('127.752.d.2.D',4,'An aircraft rescue and firefighting crew is stationed at:','["a school cafeteria", "a library", "a mall", "an airport"]'::jsonb,3,'ARFF protects aircraft operations.','original'),
('127.752.d.2.E',3,'A city posts a firefighter opening that requires an application, written exam, physical ability test and interview. These are:','["common employment processes for public sector firefighters", "no steps", "random steps", "hiring rumors"]'::jsonb,0,'Hiring is a multi-step process.','original'),
('127.752.d.2.E',4,'After passing a written test, a firefighter candidate commonly completes:','["a sports bet", "a physical ability test and interview", "a map contest", "a cooking class"]'::jsonb,1,'Selection includes physical testing.','original'),
('127.752.d.3.A',3,'In Texas, a recruit completes required courses and passes exams to become a certified firefighter under the state commission. This describes:','["a driver license", "a school diploma", "the firefighter certification process in Texas", "a library card"]'::jsonb,2,'Certification is state-regulated.','original'),
('127.752.d.3.A',4,'The Texas agency that certifies firefighters is the:','["Texas Parks Department", "Texas Lottery Commission", "Texas Racing Commission", "Texas Commission on Fire Protection"]'::jsonb,3,'TCFP certifies fire personnel.','original'),
('127.752.d.3.B',3,'A student sorts a college degree, a basic firefighter academy course and a state license into groups. This differentiates:','["education, training and certification requirements", "recipes", "sports roles", "art styles"]'::jsonb,0,'Each requirement serves a different purpose.','original'),
('127.752.d.3.B',4,'Which is an example of certification rather than education?','["a lecture note", "a state-issued firefighter certificate", "a high school diploma", "a science textbook"]'::jsonb,1,'A certificate verifies standards are met.','original'),
('127.752.d.3.C',3,'A recruit reads how the state sets minimum standards, approves training programs and reviews records. This explains the:','["role of banks", "role of insurers", "role of the TCFP in firefighter certification", "role of schools"]'::jsonb,2,'TCFP sets and enforces standards.','original'),
('127.752.d.3.C',4,'The TCFP helps protect the public by:','["selling equipment", "writing menus", "building stations", "setting minimum standards for fire personnel"]'::jsonb,3,'Standards ensure competence.','original'),
('127.752.d.5.A',3,'A firefighter adjusts how she speaks to a frightened child and then to a fellow officer, while listening and watching body cues. This shows:','["key elements of adaptive communication", "avoiding people", "one-size-fits-all speech", "silence"]'::jsonb,0,'Adaptive communication fits the audience.','original'),
('127.752.d.5.A',4,'During a fire station briefing, which action shows active listening by a recruit?','["interrupting the officer", "paying full attention and restating what the officer said", "changing the subject", "checking a phone"]'::jsonb,1,'Confirming prevents errors.','original'),
('127.752.d.5.B',3,'On a crew, clear, flexible communication helps members avoid mistakes at emergencies. This shows the:','["uselessness of talking", "value of silence", "importance of adaptive communication in the fire service", "need for secrecy"]'::jsonb,2,'Good communication improves safety and teamwork.','original'),
('127.752.d.5.B',4,'Adaptive communication improves fire service operations by:','["slowing action", "hiding facts", "raising confusion", "reducing misunderstandings among crew and the public"]'::jsonb,3,'Clarity prevents mistakes.','original'),
('127.752.d.5.C',3,'Members of a truck company share tasks, back each other up and speak respectfully. These are:','["interpersonal skills that support effective teamwork", "rumors", "solo skills", "selfish habits"]'::jsonb,0,'Teamwork needs interpersonal skill.','original'),
('127.752.d.5.C',4,'Which trait best supports teamwork on a fire crew?','["secrecy", "reliability and respect for others", "competition for credit", "arrogance"]'::jsonb,1,'Reliable, respectful members build trust.','original'),
('127.752.d.5.D',3,'Two firefighters disagree on a chore schedule, and they compromise by alternating duties. This is a conflict resolution strategy called:','["avoiding", "ignoring", "compromising", "competing"]'::jsonb,2,'Compromise meets in the middle.','original'),
('127.752.d.5.D',4,'Which conflict strategy involves giving in to the other person''s wishes?','["avoiding", "collaborating", "competing", "accommodating"]'::jsonb,3,'Accommodating yields to the other side.','original'),
('127.752.d.6.A',3,'A recruit learns that old social media posts, peer pressure, drug use and a criminal record can block a fire career. This discusses:','["personal choices that impact a fire service career", "only school", "no impacts", "only sports"]'::jsonb,0,'Conduct affects hiring.','original'),
('127.752.d.6.A',4,'Why do fire departments review a candidate''s social media?','["to find pictures", "Posts can show judgment and character", "to sell ads", "to give awards"]'::jsonb,1,'Conduct online reflects professionalism.','original'),
('127.752.d.6.B',3,'A student matches the Texas A&M Forest Service, the State Fire Marshal''s Office, the TCFP and Texas A&M Engineering Extension Service to their roles. This analyzes:','["four schools", "four sports teams", "the four Texas State Fire Service agencies", "four banks"]'::jsonb,2,'Four agencies support fire service.','original'),
('127.752.d.6.B',4,'The agency that provides firefighter training courses across Texas is:','["Texas Racing Commission", "Texas Education Agency", "Texas Lottery Commission", "Texas A&M Engineering Extension Service (TEEX)"]'::jsonb,3,'TEEX trains first responders.','original'),
('127.752.d.6.C',3,'A class compares the firefighter''s code of ethics from national fire organizations. This identifies and compares:','["professional codes of ethics relevant to the fire service", "sports rules", "dress codes only", "menus"]'::jsonb,0,'Ethics guide conduct.','original'),
('127.752.d.6.C',4,'A code of ethics for firefighters generally stresses:','["fame", "honesty, integrity and service to the public", "secrecy", "profit"]'::jsonb,1,'Core values guide the service.','original'),
('127.752.d.6.D',3,'On duty, a firefighter in Texas is required to respond to a person in danger because of a legal obligation to help. This is the:','["duty to leave", "duty to hide", "legal concept of Duty to Act", "right to ignore"]'::jsonb,2,'Duty to Act binds public safety responders.','original'),
('127.752.d.6.D',4,'Because of the Duty to Act, a firefighter who ignores a call that is within their duties may face:','["a trophy", "a vacation", "a bonus", "legal and professional consequences"]'::jsonb,3,'Failure to act can lead to liability.','original'),
('127.752.d.6.E',3,'A bystander gives first aid at a crash scene and is protected from most lawsuits by the Texas Good Samaritan Act. This describes:','["legal protection for people who give emergency aid in good faith", "a tax", "a penalty", "a licence"]'::jsonb,0,'The Act protects good-faith helpers.','original'),
('127.752.d.6.E',4,'The Texas Good Samaritan Act is found in the:','["Texas Education Code", "Texas Civil Practice and Remedies Code", "Texas Penal Code only", "Texas Tax Code"]'::jsonb,1,'Chapter 74 covers Good Samaritan.','original'),
('127.752.d.7.A',3,'A timeline shows the Great Chicago Fire, steam pumpers, motorized apparatus and thermal imaging cameras. These are:','["recipes", "sports trophies", "key milestones and technological advances in the fire service", "fashion trends"]'::jsonb,2,'Technology changed fire fighting.','original'),
('127.752.d.7.A',4,'A major change in the fire service over time was the shift from horse-drawn wagons to:','["sailboats", "bicycles", "canoes", "motorized apparatus"]'::jsonb,3,'Motorization sped response.','original'),
('127.752.d.7.B',3,'A class sorts a city ordinance, a state fire code and a national model code. This differentiates:','["local, state and federal fire laws and model codes and standards", "movie rules", "parking laws only", "school rules"]'::jsonb,0,'Fire law has several layers.','original'),
('127.752.d.7.B',4,'NFPA codes are often adopted by governments as:','["hunting rules", "model codes and standards", "school rules", "tax forms"]'::jsonb,1,'Models are adopted into law.','original'),
('127.752.d.7.C',3,'After a deadly theater fire, cities required more exits and sprinklers in public buildings. This explains how:','["exits were closed", "codes were removed", "fire losses influenced building and fire codes", "fires were ignored"]'::jsonb,2,'Tragedies drive code change.','original'),
('127.752.d.7.C',4,'Many fire code requirements for exits and alarms came from:','["ads", "fashion", "sports", "lessons learned from past deadly fires"]'::jsonb,3,'Codes evolve from losses.','original'),
('127.752.d.8.A',3,'A student describes a pumper, ladder truck and rescue truck as structural firefighting rigs. This identifies:','["structural firefighting apparatus", "carts", "boats", "tractors"]'::jsonb,0,'Apparatus serve different tasks.','original'),
('127.752.d.8.A',4,'A ladder truck is mainly designed to give firefighters:','["extra beds", "aerial access to upper floors and roofs", "a fuel tank", "cooking space"]'::jsonb,1,'Aerial ladders reach height.','original'),
('127.752.d.8.B',3,'A brush truck and a water tender are used to fight grass and forest fires. These are:','["cranes", "buses", "wildland firefighting apparatus", "ships"]'::jsonb,2,'Wildland rigs serve off-road fires.','original'),
('127.752.d.8.B',4,'A water tender at a rural wildfire is used to:','["lay roads", "tow houses", "haul firewood", "carry large amounts of water to the fire"]'::jsonb,3,'Tenders move water.','original'),
('127.752.d.8.C',3,'At an airport, a large rig can spray foam on a burning aircraft quickly. This is an:','["aircraft rescue firefighting apparatus", "school bus", "ambulance", "street sweeper"]'::jsonb,0,'ARFF trucks carry foam.','original'),
('127.752.d.8.C',4,'Aircraft rescue firefighting vehicles carry large amounts of:','["groceries", "foam and extinguishing agent", "tickets", "fuel for planes only"]'::jsonb,1,'Foam smothers fuel fires.','original'),
('127.752.d.8.D',3,'A firefighter fights a house fire in a helmet, coat, boots and breathing apparatus, but a wildland firefighter wears lighter gear. This identifies:','["sports gear", "school uniforms", "structural, wildland and aircraft firefighting PPE", "costumes"]'::jsonb,2,'PPE fits the hazard.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_98_v1'
from (values
('127.752.d.8.D',4,'Compared with structural gear, wildland PPE is generally:','["the same", "made of plastic", "heavier", "lighter and made for heat and long wear"]'::jsonb,3,'Wildland work demands mobility.','original'),
('127.752.d.8.E',3,'A gated wye, a hose clamp and a manifold are examples of:','["appliances used by structural firefighters", "carpentry tools", "cooking tools", "garden tools"]'::jsonb,0,'Appliances manage water flow.','original'),
('127.752.d.8.E',4,'A hose clamp is used to:','["heat hose", "stop water flow in a hose line", "cut hose", "roll hose"]'::jsonb,1,'Clamps pinch hose closed.','original'),
('127.752.d.8.F',3,'A halligan bar, axe and pike pole are carried on engines for forcing doors and pulling ceilings. These are:','["art tools", "office tools", "tools used by structural firefighters", "kitchen tools"]'::jsonb,2,'Hand tools support entry and overhaul.','original'),
('127.752.d.8.F',4,'A halligan tool is used primarily to:','["measure water", "carry hose", "write reports", "force open doors and windows"]'::jsonb,3,'Halligans pry.','original'),
('127.752.d.8.G',3,'A pulaski, a drip torch and a fire rake are carried on wildfire lines. These are:','["tools used by wildland firefighters", "kitchen tools", "office tools", "tile tools"]'::jsonb,0,'Wildland tools clear fuel.','original'),
('127.752.d.8.G',4,'A pulaski combines an axe with a:','["wrench", "grubbing hoe (adze)", "saw", "hammer only"]'::jsonb,1,'The pulaski digs and chops.','original'),
('127.752.d.8.H',3,'A crew uses large-diameter supply hose and smaller lightweight forestry hose for a brush fire. This differentiates:','["pipes", "cables", "hoses used by structural and wildland firefighters", "ropes"]'::jsonb,2,'Hose types suit the fire.','original'),
('127.752.d.8.H',4,'Lightweight wildland hose is useful because crews often:','["drive on it", "bury it", "never move", "carry it long distances over rough ground"]'::jsonb,3,'Weight matters on the fireline.','original'),
('127.752.d.9.A',3,'A fire chief explains that programs to reduce risk to a community before an emergency are called CRR, or:','["community risk reduction", "city road repair", "crowd rescue response", "career recruit review"]'::jsonb,0,'CRR reduces risk.','original'),
('127.752.d.9.A',4,'Community risk reduction aims to:','["end all calls", "prevent emergencies and reduce their effects", "raise fines", "sell insurance"]'::jsonb,1,'CRR prevents harm.','original'),
('127.752.d.9.B',3,'A department maps fire frequency, older homes and population to decide where to hold education programs. This is a:','["budget guess", "parade plan", "Community Risk Assessment guiding CRR", "supply count"]'::jsonb,2,'CRA finds risks.','original'),
('127.752.d.9.B',4,'A CRA helps a department decide:','["the parade route", "the uniform color", "the lunch menu", "which risks and areas need the most attention"]'::jsonb,3,'CRA directs resources.','original'),
('127.752.d.9.C',3,'A fire department partners with schools, a hospital and a housing authority to reduce home fires. These are:','["key stakeholders in CRR", "rivals", "critics only", "bystanders"]'::jsonb,0,'Stakeholders help carry out CRR.','original'),
('127.752.d.9.C',4,'The lead agency in a CRR plan is the group that:','["opposes it", "coordinates the work and partners", "funds only", "ignores it"]'::jsonb,1,'The lead agency coordinates.','original'),
('127.752.d.9.D',3,'The U.S. Fire Administration''s CRR strategies are known as the 5 E''s, such as education and enforcement. These are:','["five colors", "five classes", "five strategies for risk reduction", "five sports"]'::jsonb,2,'5 E''s: education, engineering, enforcement, economic incentive, emergency response.','original'),
('127.752.d.9.D',4,'Installing smoke alarms through a city program is an example of the 5 E''s strategy of:','["extravagance", "exclusion", "entertainment", "engineering or emergency response support"]'::jsonb,3,'Engineering uses technology and equipment.','original'),
('127.752.d.9.E',3,'City, state and federal agencies use community risk assessments to plan funding and programs. This explains how:','["governments use CRAs", "maps are drawn only", "groups ignore data", "guesses are used"]'::jsonb,0,'CRAs inform policy.','original'),
('127.752.d.9.E',4,'A federal agency might use data from many local CRAs to:','["raise fines", "target grants and programs", "close stations", "stop reports"]'::jsonb,1,'Data drives funding.','original'),
('127.752.d.10.A',3,'At a big flood response, agencies use the same words, a single plan and clear objectives under NIMS. This describes the:','["sports plan", "menu plan", "purpose of NIMS", "school plan"]'::jsonb,2,'NIMS standardizes response.','original'),
('127.752.d.10.A',4,'NIMS stands for:','["Neighborhood Inspection Map System", "National Insurance Market Survey", "North Island Medical Service", "National Incident Management System"]'::jsonb,3,'NIMS coordinates agencies.','original'),
('127.752.d.10.B',3,'The Incident Commander, section chiefs and branches make up the:','["components of the ICS structure", "cheer squad", "school bus route", "kitchen crew"]'::jsonb,0,'ICS organizes roles.','original'),
('127.752.d.10.B',4,'In ICS, the Incident Commander is responsible for:','["only finance", "overall management of the incident", "only logistics", "only media"]'::jsonb,1,'IC leads the response.','original'),
('127.752.d.11.A',3,'A city fire marshal enforces a local fire code and has final say over occupancy. This is the:','["landlord", "mail carrier", "authority having jurisdiction (AHJ)", "tenant"]'::jsonb,2,'AHJ enforces codes.','original'),
('127.752.d.11.A',4,'The AHJ is the organization or person that:','["sells equipment", "owns the building", "writes the newspaper", "has legal authority to enforce codes"]'::jsonb,3,'AHJ means jurisdiction.','original'),
('127.752.d.11.B',3,'A department chart shows a chief, deputy chiefs, captains, lieutenants and firefighters in order of rank. This is the:','["hierarchical structure of a fire department", "supply list", "parade order", "lunch line"]'::jsonb,0,'Rank structure clarifies authority.','original'),
('127.752.d.11.B',4,'In a typical fire department chain of command, a lieutenant reports to a:','["firefighter", "captain", "civilian volunteer", "recruit"]'::jsonb,1,'Lower ranks report up.','original'),
('127.752.d.11.C',3,'A fire chief administers the budget, sets policy and represents the department to elected officials. These are the:','["roles of a vendor", "roles of a recruit", "roles and responsibilities of the fire chief", "roles of a student"]'::jsonb,2,'Chiefs lead and manage.','original'),
('127.752.d.11.C',4,'The fire chief is primarily accountable for:','["only driving", "only training", "only cleaning", "the overall operation of the department"]'::jsonb,3,'The chief answers for all of it.','original'),
('127.752.d.12.A',3,'Inspectors review building plans, check exits and teach fire safety at schools. These are functions of the:','["fire prevention division", "training division", "dispatch center", "vehicle maintenance shop"]'::jsonb,0,'Prevention reduces fires.','original'),
('127.752.d.12.A',4,'A fire prevention division conducts:','["engine repairs", "inspections and public education", "911 calls", "academy testing"]'::jsonb,1,'Prevention = inspections and education.','original'),
('127.752.d.12.B',3,'A hazmat team and a technical rescue team are part of:','["grounds crew", "cafeteria", "fire service special operations", "clerical staff"]'::jsonb,2,'Special ops handle complex rescues.','original'),
('127.752.d.12.B',4,'Special operations units are trained for:','["fundraisers", "parades", "classes only", "hazardous materials and technical rescues"]'::jsonb,3,'They handle unusual hazards.','original'),
('127.752.d.12.C',3,'New recruits and veteran firefighters practice skills and take refresher courses through the:','["fire training division", "dispatch", "fire prevention division", "finance office"]'::jsonb,0,'Training keeps skills current.','original'),
('127.752.d.12.C',4,'Which task is typically handled by the training division?','["fixing engines", "coordinating academy classes and drills", "inspecting buildings", "answering 911 calls"]'::jsonb,1,'Training runs classes.','original'),
('127.752.d.12.D',3,'Mechanics test pumps and repair brakes on engines. These are functions of the:','["dispatch", "training", "equipment maintenance division", "prevention"]'::jsonb,2,'Maintenance keeps rigs ready.','original'),
('127.752.d.12.D',4,'The maintenance division makes sure apparatus and tools are:','["decorated", "sold", "hidden", "safe and ready for use"]'::jsonb,3,'Ready equipment saves time.','original'),
('127.752.d.12.E',3,'A call taker receives an emergency call, gathers details and sends units. This describes core responsibilities of a:','["911 communication center", "mess hall", "print shop", "parts room"]'::jsonb,0,'911 centers dispatch.','original'),
('127.752.d.12.E',4,'A 911 dispatcher''s first job on an emergency call is to:','["play music", "gather the location and nature of the emergency", "ask for payment", "end the call"]'::jsonb,1,'Location comes first.','original'),
('127.752.d.12.F',3,'During a hurricane, a county office coordinates shelters, resources and agencies. This is the work of the:','["parks office", "library", "Office of Emergency Management", "fire prevention bureau"]'::jsonb,2,'OEM coordinates large disasters.','original'),
('127.752.d.12.F',4,'The Office of Emergency Management primarily:','["writes tickets", "repairs engines", "fights house fires", "plans for and coordinates disaster response"]'::jsonb,3,'OEM coordinates across agencies.','original'),
('127.752.d.13.A',3,'A science teacher describes a rapid chemical reaction that gives off heat and light and needs fuel, oxygen and heat. This describes:','["combustion", "mud", "ice", "rust"]'::jsonb,0,'Fire = rapid oxidation with heat and light.','original'),
('127.752.d.13.A',4,'Fire is best defined as a:','["frozen reaction", "rapid oxidation process that releases heat and light", "sound wave", "slow rusting"]'::jsonb,1,'Combustion is rapid oxidation.','original'),
('127.752.d.13.B',3,'The fire triangle has heat, fuel and oxygen, and the fire tetrahedron adds a fourth part. This identifies the:','["parts of a hose", "apparatus", "components of the fire triangle and tetrahedron", "ladder rails"]'::jsonb,2,'The tetrahedron adds the chain reaction.','original'),
('127.752.d.13.B',4,'The fourth side of the fire tetrahedron is the:','["water", "wind", "smoke", "uninhibited chemical chain reaction"]'::jsonb,3,'The chain reaction sustains flaming fire.','original'),
('127.752.d.13.C',3,'A student sorts ice, water and steam into groups. This describes the physical characteristics of:','["the three states of matter", "colors", "fuel types", "rock types"]'::jsonb,0,'Solid, liquid, gas.','original'),
('127.752.d.13.C',4,'Which state of matter has no definite shape or volume?','["solid", "gas", "ice", "liquid"]'::jsonb,1,'Gases fill their container.','original'),
('127.752.d.13.D',3,'Oxygen helps a fire burn while wood supplies energy as the burning material. This differentiates an:','["smoke and fog", "water and ice", "oxidizing agent and a fuel", "heat and light"]'::jsonb,2,'Oxidizer + fuel.','original'),
('127.752.d.13.D',4,'In a fire, oxygen acts as the:','["heat source", "fuel", "extinguisher", "oxidizing agent"]'::jsonb,3,'Oxygen supports burning.','original'),
('127.752.d.13.E',3,'When wood is heated, it gives off flammable vapors before it ignites. This is:','["pyrolysis", "freezing", "evaporation", "refrigeration"]'::jsonb,0,'Pyrolysis is thermal decomposition.','original'),
('127.752.d.13.E',4,'Pyrolysis helps fire spread by:','["cooling the fuel", "creating flammable gases from solid fuel", "removing oxygen", "stopping heat"]'::jsonb,1,'Pyrolysis produces vapors.','original'),
('127.752.d.13.F',3,'A vapor-air mixture with too much fuel to burn is ''fuel rich'', and too little fuel is:','["fuel heavy", "fuel wet", "fuel lean", "fuel cold"]'::jsonb,2,'Flammable range has limits.','original'),
('127.752.d.13.F',4,'A fuel-lean mixture contains:','["no air", "too much fuel", "only water", "too little fuel to burn"]'::jsonb,3,'Lean = not enough fuel.','original'),
('127.752.d.13.G',3,'A cup of boiling water has a higher temperature than a bathtub of warm water but less total energy. This analyzes the difference between:','["temperature and heat", "color and shape", "weight and size", "speed and mass"]'::jsonb,0,'Temperature is intensity; heat is energy.','original'),
('127.752.d.13.G',4,'Heat is best described as:','["a measure of speed", "thermal energy", "humidity", "a thermometer reading"]'::jsonb,1,'Heat is energy transfer.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
